package com.loyu3c.rental;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class LeaseAttachmentsTest {
    private final String oldPhoto="11111111-1111-1111-1111-111111111111.jpg",newPhoto="22222222-2222-2222-2222-222222222222.jpg",anotherPhoto="33333333-3333-3333-3333-333333333333.jpg",pdf="44444444-4444-4444-4444-444444444444.pdf";
    private JSONObject original()throws Exception{return new JSONObject().put("tenant","租客").put("initialMeterPhoto",oldPhoto).put("contractFile",pdf).put("contractName","原合約.pdf");}
    @Test public void selectingAttachmentsDoesNotMutateSavedLeaseAndCancelDiscardsOnlyNewFiles()throws Exception{JSONObject original=original();String before=original.toString();JSONObject draft=LeaseAttachments.draft(original);LeaseAttachments.select(draft,newPhoto,"",false);LeaseAttachments.remove(draft,true);assertEquals(before,original.toString());assertEquals(Set.of(newPhoto),LeaseAttachments.discard(draft,false));assertFalse(LeaseAttachments.discard(draft,false).contains(oldPhoto));assertFalse(LeaseAttachments.discard(draft,false).contains(pdf));}
    @Test public void saveCommitsBothAttachmentsAndDiscardsSupersededDraftPhoto()throws Exception{JSONObject draft=LeaseAttachments.draft(null);LeaseAttachments.select(draft,newPhoto,"",false);LeaseAttachments.select(draft,anotherPhoto,"",false);LeaseAttachments.select(draft,pdf,"長檔名租賃合約.pdf",true);JSONObject lease=new JSONObject();LeaseAttachments.apply(draft,lease);assertEquals(anotherPhoto,lease.getString("initialMeterPhoto"));assertEquals(pdf,lease.getString("contractFile"));assertEquals("長檔名租賃合約.pdf",lease.getString("contractName"));assertEquals(Set.of(newPhoto),LeaseAttachments.discard(draft,true));assertEquals(Set.of(newPhoto,anotherPhoto,pdf),LeaseAttachments.discard(draft,false));}
    @Test public void draftRoundTripPreservesIncompleteFieldsAndPendingAttachments()throws Exception{JSONObject draft=LeaseAttachments.draft(original());LeaseAttachments.select(draft,newPhoto,"",false);JSONObject session=new JSONObject().put("values",new JSONObject().put("tenant","").put("rent","12,").put("start","")).put("attachments",draft).put("scroll",320);JSONObject restored=new JSONObject(session.toString());assertEquals("12,",restored.getJSONObject("values").getString("rent"));assertEquals("",restored.getJSONObject("values").getString("tenant"));assertEquals(320,restored.getInt("scroll"));assertEquals(Set.of(newPhoto),LeaseAttachments.discard(restored.getJSONObject("attachments"),false));}
    @Test public void removeIsDeferredAndOriginalFilesNeverBecomeDraftOwned()throws Exception{JSONObject original=original(),draft=LeaseAttachments.draft(original);LeaseAttachments.remove(draft,false);LeaseAttachments.remove(draft,true);assertTrue(LeaseAttachments.discard(draft,false).isEmpty());JSONObject next=new JSONObject(original.toString());LeaseAttachments.apply(draft,next);assertFalse(next.has("initialMeterPhoto"));assertFalse(next.has("contractFile"));assertFalse(next.has("contractName"));assertTrue(original.has("initialMeterPhoto"));}
    @Test public void unsafeFileNameDoesNotReplaceCurrentAttachment()throws Exception{JSONObject draft=LeaseAttachments.draft(original());try{LeaseAttachments.select(draft,"../outside.pdf","x",true);fail();}catch(IllegalArgumentException expected){}assertEquals(pdf,draft.getString("pdf"));assertTrue(LeaseAttachments.discard(draft,false).isEmpty());}
}
